From cdc46b2a54badeb9aadb1e7fd8ab83845e3fab0f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:18:17 +0100
Subject: [PATCH] backlighthelper: keep the panel's device while its connector
 is disabled

Brightness set as the screen woke up found the panel's connector still
disabled, so the helper took another GPU's raw backlight as reference
and rescaled the value. Keep using the devices of a connector then.

BUG: 523341
---
 daemon/controllers/backlighthelper_linux.cpp | 20 +++++++++++++++-----
 1 file changed, 15 insertions(+), 5 deletions(-)

diff --git a/daemon/controllers/backlighthelper_linux.cpp b/daemon/controllers/backlighthelper_linux.cpp
index 5bead8629..e09b1daae 100644
--- a/daemon/controllers/backlighthelper_linux.cpp
+++ b/daemon/controllers/backlighthelper_linux.cpp
@@ -99,7 +99,7 @@ QStringList BacklightHelper::getBacklightTypeDevices() const

     QFile file;
     QByteArray buffer;
-    QStringList firmware, platform, rawEnabled, rawAll;
+    QStringList firmware, platform, rawEnabled, rawConnector, rawAll;

     for (const QString &interface : interfaces) {
         file.setFileName(BACKLIGHT_SYSFS_PATH + interface + u"/type");
@@ -115,10 +115,14 @@ QStringList BacklightHelper::getBacklightTypeDevices() const
         } else if (buffer == "raw") {
             QFile enabled(BACKLIGHT_SYSFS_PATH + interface + u"/device/enabled");
             rawAll.append(BACKLIGHT_SYSFS_PATH + interface);
-            if (enabled.open(QIODevice::ReadOnly | QIODevice::Text) && enabled.readLine().trimmed() == "enabled") {
-                // this backlight device is connected to a display, so append
-                // it to rawEnabled list
-                rawEnabled.append(BACKLIGHT_SYSFS_PATH + interface);
+            if (enabled.open(QIODevice::ReadOnly | QIODevice::Text)) {
+                // this backlight device belongs to a display connector
+                rawConnector.append(BACKLIGHT_SYSFS_PATH + interface);
+                if (enabled.readLine().trimmed() == "enabled") {
+                    // this backlight device is connected to a display, so append
+                    // it to rawEnabled list
+                    rawEnabled.append(BACKLIGHT_SYSFS_PATH + interface);
+                }
             }
         } else {
             qCWarning(POWERDEVIL) << "Interface type not handled" << buffer;
@@ -136,6 +140,12 @@ QStringList BacklightHelper::getBacklightTypeDevices() const
     if (!rawEnabled.isEmpty())
         return rawEnabled;

+    // The display's connector can be disabled for a moment, e.g. while the screen
+    // turns back on: keep using its device then, so that the brightness isn't
+    // rescaled against the maximum of another GPU's device
+    if (!rawConnector.isEmpty())
+        return rawConnector;
+
     if (!rawAll.isEmpty())
         return rawAll;

